def _dispatch_isolated_view(
    self, dispatch_id: str, adapter_id: str
) -> dict:
    """隔离成功/重放响应体 V（三键固定序，state 恒为 isolated）。"""
    return {
        "dispatch_id": dispatch_id,
        "adapter_id": adapter_id,
        "state": "isolated",
    }

def _dispatch_isolate_event_locked(
    self, wallet_id: str, dispatch_id: str
) -> Optional[dict]:
    """返回某派发唯一的 chain_dispatch_isolated 事件（调用方持锁）；
    未隔离返回 None；重复隔离事件是不可对账现场（RecoveryError）。"""
    grouped = self._audit.chain_dispatch_isolated_events(
        wallet_id
    ).get(dispatch_id)
    if not grouped:
        return None
    if len(grouped) != 1:
        raise RecoveryError(
            f"wallet {wallet_id!r} has multiple "
            f"chain_dispatch_isolated events for {dispatch_id!r}"
        )
    return grouped[0]

def _dispatch_isolated_events_strict(
    self, wallet_id: str
) -> list[dict]:
    """返回该钱包全部 chain_dispatch_isolated 事件（按 seq 升序）并
    逐条严格校验**形状**（外层七字段键序、request_id==dispatch_id、
    actor_id/reason 恒为 null、details 恰为三键 V 且键序固定
    dispatch_id,adapter_id,state、state 恒为 isolated、adapter_id 为
    安全标识）。

    这里只做与现场无关的形状校验；与派发请求/健康表/操作/结果/接管的
    语义复核在 :meth:`_reconcile_chain_dispatch_isolated_events` 按事件
    seq 完成。任何形状畸形都是不可对账现场（RecoveryError）。纯只读，
    不分配 seq。"""
    events = self._audit.events_by_type(
        wallet_id, audit.TYPE_CHAIN_DISPATCH_ISOLATED
    )
    seen: set[str] = set()
    for event in events:
        if list(event) != list(_AUDIT_OUTER_KEY_ORDER):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_dispatch_isolated "
                "event whose outer fields are out of the canonical order"
            )
        dispatch_id = event.get("request_id")
        if (
            not isinstance(dispatch_id, str)
            or not ROTATION_ID_RE.match(dispatch_id)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_dispatch_isolated "
                "event with a malformed dispatch_id"
            )
        if dispatch_id in seen:
            raise RecoveryError(
                f"wallet {wallet_id!r} has multiple "
                f"chain_dispatch_isolated events for {dispatch_id!r}"
            )
        seen.add(dispatch_id)
        # 隔离无审批/无操作人：actor_id 与 reason 恒为 null。
        if (
            event.get("actor_id") is not None
            or event.get("reason") is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} has a non-null actor_id or reason"
            )
        details = event.get("details")
        if (
            not isinstance(details, dict)
            or list(details)
            != list(self._DISPATCH_ISOLATED_VIEW_KEY_ORDER)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} has malformed details"
            )
        if details["dispatch_id"] != dispatch_id:
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} details dispatch_id disagrees with its "
                "request_id"
            )
        if not (
            isinstance(details["adapter_id"], str)
            and ROTATION_ID_RE.match(details["adapter_id"])
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} has a malformed adapter_id"
            )
        if details["state"] != "isolated":
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} has a state other than isolated"
            )
    return events

def _reconcile_chain_dispatch_isolated_events(
    self, wallet_id: str
) -> None:
    """按 seq 严格复核全部 chain_dispatch_isolated 事件（调用方须持
    钱包事务锁）。

    每条隔离都以其**提交之前**的现场复核在线首提的全部前置：

    - 同一 dispatch_id 的 chain_dispatch_requested 必须先于隔离事件
      提交（派发在先）；
    - 隔离提交之前最近一条 chain_adapter_health 快照必须存在，且派发
      原适配器在该快照中显式为 ``down``（无快照/缺席/up 都矛盾）；
    - 隔离时资产操作仍为 pending（该操作的提交点不得早于隔离）；
    - 隔离之前该派发没有任何 chain_dispatch_result 与
      chain_dispatch_taken_over（result/takeover/isolate 互斥在前）；
    - 隔离之后、接管之前同样不得有 result（隔离只允许后续 takeover
      由新适配器重新播链）；未接管的隔离派发之后不得再有任何 result；
    - actor_id/reason 为 null、每派发至多一条隔离（形状校验保证）。

    任一矛盾都 fail-closed（RecoveryError，保留现场）。纯只读，不记
    事件、不改 seq、不写状态。"""
    events = self._dispatch_isolated_events_strict(wallet_id)
    if not events:
        return
    requests = self._dispatch_events_strict(wallet_id)
    request_by_dispatch = {
        event["request_id"]: event for event in requests
    }
    # 适配器健康快照按 seq 升序（形状已在 _chain_adapter_health_events_strict
    # 严格校验）：隔离前置取其 seq 之前的最后一条。
    health_events = self._chain_adapter_health_events_strict(wallet_id)
    # 各资产操作的提交 seq。
    committed_seq: dict[str, int] = {}
    for committed in self._audit.events_by_type(
        wallet_id, audit.TYPE_ASSET_OPERATION_COMMITTED
    ):
        request_id = committed.get("request_id")
        if isinstance(request_id, str):
            committed_seq[request_id] = committed["seq"]
    result_events = self._audit.events_by_type(
        wallet_id, audit.TYPE_CHAIN_DISPATCH_RESULT
    )
    results_by_dispatch: dict[str, list[dict]] = {}
    for event in result_events:
        results_by_dispatch.setdefault(
            event["request_id"], []
        ).append(event)
    takeover_by_dispatch = {
        event["request_id"]: event
        for event in self._dispatch_taken_over_events_strict(wallet_id)
    }
    for event in events:
        details = event["details"]
        dispatch_id = details["dispatch_id"]
        seq = event["seq"]
        adapter_id = details["adapter_id"]
        request = request_by_dispatch.get(dispatch_id)
        if request is None or request["seq"] >= seq:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a chain_dispatch_isolated "
                f"event for {dispatch_id!r} without a preceding dispatch "
                "request"
            )
        saved_request = request["details"]
        if saved_request["adapter_id"] != adapter_id:
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} adapter disagrees with its dispatch "
                "request"
            )
        # 事前健康表：seq 之前最后一条快照必须存在且原适配器显式 down。
        health_table = None
        for health_event in health_events:
            if health_event["seq"] < seq:
                health_table = health_event["details"]["adapters"]
            else:
                break
        if (
            health_table is None
            or health_table.get(adapter_id) != "down"
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} has no preceding health snapshot with "
                "its adapter explicitly down"
            )
        # 隔离时操作必须仍为 pending。
        operation_id = saved_request["operation_id"]
        operation_commit_seq = committed_seq.get(operation_id)
        if operation_commit_seq is not None and operation_commit_seq < seq:
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} follows a committed asset operation"
            )
        # 与 result/takeover 的先后互斥：隔离之前不得有 result 或接管；
        # 隔离之后只允许 takeover（其后新适配器 result 由结果对账复核）。
        takeover = takeover_by_dispatch.get(dispatch_id)
        for result in results_by_dispatch.get(dispatch_id, []):
            if result["seq"] < seq:
                raise RecoveryError(
                    f"wallet {wallet_id!r} chain_dispatch_isolated "
                    f"{dispatch_id!r} follows an earlier dispatch result"
                )
            if takeover is None or result["seq"] < takeover["seq"]:
                raise RecoveryError(
                    f"wallet {wallet_id!r} has a dispatch result between "
                    f"isolation and takeover for {dispatch_id!r}"
                )
        if takeover is not None and takeover["seq"] < seq:
            raise RecoveryError(
                f"wallet {wallet_id!r} chain_dispatch_isolated "
                f"{dispatch_id!r} follows an earlier takeover"
            )

def post_chain_dispatch_isolate(
    self, wallet_id: str, dispatch_id: object
) -> tuple[int, dict]:
    """隔离一笔尚在途但原适配器已显式熔断的派发，返回
    (HTTP 状态码, 视图 V={dispatch_id,adapter_id,state})。

    请求体恰为空 JSON 对象 ``{}``（HTTP 边界拦键集）；路径 D 须匹配
    安全标识，非法 400；钱包/派发未知 404。首提前置：派发所属资产
    操作仍为 pending；该派发尚无 result、无 takeover、无 isolate；派
    发原适配器（dispatch 请求中的 adapter_id）在**当前**健康表中显式
    为 ``down``（健康表未配置、适配器缺席或为 up 一律 409）。任一不
    满足 409 且零副作用（不追加事件、现场不变）。

    首提 201 返回 V（state="isolated"）；同 D 重放优先 200 返回同一
    V（不复查健康表与现状）。chain_dispatch_isolated 是唯一提交事件
    （request_id=D、actor_id/reason=null、details=V）；钱包锁内并发
    只有一个 201，重放不记事件。隔离后旧适配器 result 一律 409；该派
    发可再经 takeover 由新适配器接管（failed/isolate 二选一前置）。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：存在性在锁内、heal 之后先判定
            self._get_wallet_or_404(wallet_id)
            # 持锁访问先重放策略、票、派发请求/结果/确认/结算/重组/
            # 接管/隔离、操作与相邻提交事件：矛盾现场 fail-closed。
            self._reconcile_chain_state_locked(wallet_id)
            if (
                not isinstance(dispatch_id, str)
                or not ROTATION_ID_RE.match(dispatch_id)
            ):
                raise ServiceError(
                    400,
                    "dispatch_id must match [A-Za-z0-9_-]{1,128}",
                )

            # 同 D 重放优先于一切现状判定：已隔离即 200 返回同一 V，
            # 不复查健康表（事后把适配器翻回 up 不影响幂等重放）。
            isolate_event = self._dispatch_isolate_event_locked(
                wallet_id, dispatch_id
            )
            if isolate_event is not None:
                return 200, dict(isolate_event["details"])

            # 404：派发请求未知
            requests = self._audit.chain_dispatch_requested_events(
                wallet_id
            )
            grouped = requests.get(dispatch_id)
            if not grouped:
                raise ServiceError(
                    404, f"dispatch {dispatch_id!r} not found"
                )
            if len(grouped) != 1:
                raise RecoveryError(
                    f"wallet {wallet_id!r} has multiple "
                    f"chain_dispatch_requested events for "
                    f"{dispatch_id!r}"
                )
            request_details = grouped[0]["details"]
            adapter_id = request_details["adapter_id"]

            # 409：资产操作必须仍为 pending
            record = self._store.get_asset_operation(
                wallet_id, request_details["operation_id"]
            )
            if record is None:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dispatch {dispatch_id!r} "
                    "refers to an unknown asset operation"
                )
            if record["state"] != "pending":
                raise ServiceError(
                    409,
                    f"asset operation "
                    f"{request_details['operation_id']!r} is "
                    f"{record['state']}, not pending",
                )

            # 409：已有 result / takeover，不能隔离
            result_group = (
                self._audit.chain_dispatch_result_events(wallet_id).get(
                    dispatch_id
                )
                or []
            )
            if result_group:
                raise ServiceError(
                    409,
                    f"dispatch {dispatch_id!r} already has a result",
                )
            if (
                self._dispatch_takeover_event_locked(
                    wallet_id, dispatch_id
                )
                is not None
            ):
                raise ServiceError(
                    409,
                    f"dispatch {dispatch_id!r} has already been taken over",
                )

            # 409：原适配器必须在**当前**健康表中显式 down；健康表
            # 未配置或该适配器缺席视为 up（不熔断/不可隔离）。
            adapters = self._chain_adapters_locked(wallet_id)
            if adapters is None or adapters.get(adapter_id) != "down":
                raise ServiceError(
                    409,
                    f"chain adapter {adapter_id!r} is not explicitly "
                    "down in the current health table",
                )

            None,
        )
        if matched is None:
            return
        event["details"] = {key: details[key] for key in matched}
        return
    if set(details) != set(order):
        return
    event["details"] = {key: details[key] for key in order}


def _canonicalize_sorted(value: object) -> object:
    """递归重排为 sort_keys 规范序（与 WalletStore._atomic_write 同字节）。"""
    if isinstance(value, dict):
        return {k: _canonicalize_sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_canonicalize_sorted(item) for item in value]
    return value


#: 重组补偿提交事件 asset_operation_committed 的 details（即 committed 视图
#: R）固定键序：operation_id,asset_id,delta,state,balance,version。仅适用
#: 于紧邻 chain_dispatch_reorged 之后、同 request_id 的那一条提交事件（重组
#: 三事件批的收尾事件）；普通提交/链上确认/仲裁/结算的提交事件维持既有
#: sort_keys 落盘序，行为不变。
_ASSET_OPERATION_R_KEY_ORDER = (
    "operation_id",
    "asset_id",
    "delta",
    "state",
    "balance",
    "version",
)


def _reorg_compensation_commit(events: list, index: int) -> bool:
    """判定物理序列 index 处的 asset_operation_committed 事件是否为重组补偿
    三事件批（chain_dispatch_confirmation(state=reorged) +
    chain_dispatch_reorged + asset_operation_committed）的收尾提交事件：按
    seq 其紧邻前一条必须是同 request_id 的 chain_dispatch_reorged。"""
    event = events[index]
    if not isinstance(event, dict):
        return False
    seq = event.get("seq")
    if not isinstance(seq, int) or isinstance(seq, bool):
        return False
    predecessor = next(
        (
            candidate
            for candidate in events
            if isinstance(candidate, dict) and candidate.get("seq") == seq - 1
        ),
        None,
    )
    return (
        event.get("type") == TYPE_ASSET_OPERATION_COMMITTED
        and isinstance(predecessor, dict)
        and predecessor.get("type") == TYPE_CHAIN_DISPATCH_REORGED
        and event.get("request_id") is not None
        and event.get("request_id") == predecessor.get("request_id")
    )


def _order_reorg_committed_details(events: list) -> None:
    """把重组补偿提交事件（紧邻 chain_dispatch_reorged 的同 request_id
    asset_operation_committed）的 details 就地重排为 R 键序。

    仅当 details 键集恰为 R 六键时重排；畸形现场留给语义对账 fail-closed。
    其余提交事件的 details 维持原序（普通提交维持 sort_keys 序）。"""
    for index, event in enumerate(events):
        if not _reorg_compensation_commit(events, index):
            continue
        details = event.get("details")
        if isinstance(details, dict) and set(details) == set(
            _ASSET_OPERATION_R_KEY_ORDER
        ):
            event["details"] = {
                key: details[key] for key in _ASSET_OPERATION_R_KEY_ORDER
            }


def _canonical_event(
    event: object, preserve_details_order: bool = False
) -> object:
    """单条事件的落盘规范形：七字段 sort_keys，惟既定类型 details 保序。

    preserve_details_order 为真时，details 即使不在 _DETAILS_KEY_ORDER
    （重组补偿提交事件 asset_operation_committed）也按已归一的 R 键序原样
    保序，不随 sort_keys 重排。"""
    if not isinstance(event, dict):
        return _canonicalize_sorted(event)
    canonical = {}
    for key in sorted(event):
        value = event[key]
        if key == "details" and isinstance(value, dict) and (
            event.get("type") in _DETAILS_KEY_ORDER
            or preserve_details_order
        ):
            # 保留构造/读取时已归一为 README 既定顺序的 details 键序
            canonical[key] = value
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _canonical_log(data: dict) -> dict:
    """审计日志整体落盘规范形（顶层与各事件 sort_keys，既定 details 保序）。"""
    canonical = {}
    for key in sorted(data):
        value = data[key]
        if key == "events" and isinstance(value, list):
            # 重组补偿提交事件的 details 按 README 的 R 序落盘（不随
            # sort_keys 被重排为 state 先于 delta 的规范序）。
            _order_reorg_committed_details(value)
            canonical[key] = [
                _canonical_event(
                    event,
                    preserve_details_order=_reorg_compensation_commit(
                        value, index
                    ),
                )
                for index, event in enumerate(value)
            ]
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _atomic_write_log(path: str, data: dict) -> None:
    """与 WalletStore._atomic_write 相同的临时文件 + 原子替换；序列化按
    _canonical_log（既定事件类型的 details 按 README 既定键序落盘）。"""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_canonical_log(data), f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


class AuditStore:
    """审计事件日志的仅追加文件存储（一个钱包一个文件）。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._audit_dir = os.path.join(data_dir, "audit")
        self._lock = threading.Lock()

    def _path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._audit_dir, wallet_id + ".json")

    @staticmethod
    def _event_shape_ok(event: object) -> bool:
        """单条审计事件的严格形状：

        seq 为非布尔正整数；type 为非空字符串；at 为可解析的 UTC 时间；
        request_id/actor_id/reason 为 null 或字符串；details 为对象。
        details 内部各事件类型的语义由相应恢复路径（轮换链/会话动作序列/
        账本对账）负责，全局加载不重复解释。"""
        if not isinstance(event, dict):
            return False
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            return False
        if not isinstance(event.get("type"), str) or not event["type"]:
            return False
        if parse_utc_iso(event.get("at")) is None:
            return False
        for key in ("request_id", "actor_id", "reason"):
            value = event.get(key)
            if value is not None and not isinstance(value, str):
                return False
        if not isinstance(event.get("details"), dict):
            return False
        return True

    def _read_strict(self, wallet_id: str) -> Optional[dict]:
        """读取并严格校验审计文件；文件不存在返回 None。

        以下现场一律视为不可对账的数据损坏（CorruptDataError），绝不静默
        归一为空日志后覆盖历史：JSON 不可解析、顶层不是对象、events 缺失
        或不是列表、wallet_id 字段不匹配、任一事件形状非法、seq 不从 1
        起 / 不连续 / 有重号、记录的 next_seq 与实际最大 seq 矛盾。
        """
        path = self._path(wallet_id)
        data = WalletStore._read_json(path)
        if data is None:
            return None
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"audit log {path!r} top-level value is not an object"
            )
        recorded_wallet = data.get("wallet_id")
        if recorded_wallet is not None and recorded_wallet != wallet_id:
            raise CorruptDataError(
                f"audit log {path!r} wallet_id {recorded_wallet!r} does not "
                f"match its file name {wallet_id!r}"
            )
        events = data.get("events")
        if "events" not in data or not isinstance(events, list):
            raise CorruptDataError(
                f"audit log {path!r} has no list-valued 'events'"
            )
        seqs: list[int] = []
        for event in events:
            if not self._event_shape_ok(event):
                raise CorruptDataError(
                    f"audit log {path!r} has a malformed event"
                )
            seqs.append(event["seq"])
        # seq 必须恰为 1..N：不重号、不缺口、单调（物理顺序允许被外部重排，
        # 查询始终按 seq 升序；但 seq 集合本身必须连续）。
        if sorted(seqs) != list(range(1, len(seqs) + 1)):
            raise CorruptDataError(
                f"audit log {path!r} has a non-contiguous or duplicated seq"
            )
        stored_next = data.get("next_seq")
        if stored_next is not None:
            if (
                not isinstance(stored_next, int)
                or isinstance(stored_next, bool)
                or stored_next != len(events) + 1
            ):
                raise CorruptDataError(
                    f"audit log {path!r} next_seq disagrees with its events"
                )
        # 既定事件类型的 details 在内存视图中归一为 README 既定键序，
        # 使查询/重建/重写（落盘与灾备）都按该顺序保序。
        #
        # 但归一化会就地重排键序，必须**先**对落盘原序严格的类型核对其
        # 落盘 details 键序：错序即外部篡改/不可对账（RecoveryError），
        # 绝不先归一再校验而把错序静默抹平。审计 JSON 本身解析失败已在
        # WalletStore._read_json 处抛 CorruptDataError。
        for event in events:
            if event.get("type") in _STRICT_OUTER_ORDER_TYPES and list(
                event
            ) != list(_OUTER_KEY_ORDER):
                raise RecoveryError(
                    f"audit log {path!r} has a "
                    f"{event.get('type')} event whose outer fields are out "
                    "of the canonical order"
                )
            if (
                event.get("type") in _STRICT_DETAILS_ORDER_TYPES
                and not _stored_details_has_canonical_order(event)
            ):
                raise RecoveryError(
                    f"audit log {path!r} has a "
                    f"{event.get('type')} event whose details are out of "
                    "the canonical order"
                )
        # 重组补偿三事件批的收尾提交事件（seq-1 为同 request_id 的
        # chain_dispatch_reorged）的 asset_operation_committed.details 必须
        # 按 README 的 R 序落盘；错序即在归一化之前 fail-closed，绝不先
        # 归一而抹平重排。按 seq 邻接判定（物理顺序允许被外部重排）。
        by_seq = {event["seq"]: event for event in events}
        for event in events:
            if event.get("type") != TYPE_ASSET_OPERATION_COMMITTED:
                continue
            predecessor = by_seq.get(event["seq"] - 1)
            if not (
                isinstance(predecessor, dict)
                and predecessor.get("type") == TYPE_CHAIN_DISPATCH_REORGED
                and predecessor.get("request_id") is not None
                and predecessor.get("request_id") == event.get("request_id")
            ):
                continue
            details = event.get("details")
            if (
                not isinstance(details, dict)
                or list(details) != list(_ASSET_OPERATION_R_KEY_ORDER)
            ):
                raise RecoveryError(
                    f"audit log {path!r} has an "
                    "asset_operation_committed event for a reorg "
                    "compensation whose details are out of the R order"
                )
        for event in events:
            _order_event_details(event)
        # 重组补偿提交事件的 details 在内存视图中同样归一为 R 序（落盘与
        # 恢复一致）；普通提交事件维持既有 sort_keys 序不变。
        _order_reorg_committed_details(events)
        return data

    def check_log(self, wallet_id: str) -> None:
        """只读严格校验审计文件；损坏抛 CorruptDataError/OSError。
        文件不存在（尚无事件）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_strict(wallet_id)

    def list_audit_wallet_ids(self) -> list[str]:
        """返回存在审计文件的全部 wallet_id（启动恢复扫描用）。"""
        try:
            names = os.listdir(self._audit_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _safe_id_match(name[: -len(".json")])
        )

    def _read(self, wallet_id: str) -> Optional[dict]:
        return self._read_strict(wallet_id)

    def append_event(self, wallet_id: str, event: dict) -> dict:
        """原子追加一条事件，分配下一个 seq 并持久化，返回含 seq/at 的记录。

        seq 从 1 起；同一 wallet 的写入在此串行化。调用方负责在更大的
        每钱包事务锁内把状态变更与本调用绑定（失败时回滚状态）。

    """返回该钱包全部 share_participant_reinstated 事件，按 request_id
    （绑定 id）分组，组内按 seq 升序。

    份额槽位绑定仅由这些事件持久化（事件是唯一提交点）：在线幂等重放
    与崩溃恢复据此判定每个绑定 id 是否已提交及其参数。每个绑定 id 至多
    一条有效事件（重复属不可对账现场，由恢复判定）。纯只读，不分配
    seq。"""
    return self._events_grouped_by_request(
        wallet_id, TYPE_SHARE_PARTICIPANT_REINSTATED
    )

